@@ -190,42 +190,53 @@ export async function imageGenGemini({
     throw new Error('No image data received');
   }

-  // Handle background processing asynchronously
-  triggerBackgroundProcessing(imageGeneration.id, {
-    images: result.images,
-    status: RequestStatus.COMPLETED
-  })
-    .then(({ imageGeneration, imageIds }) => {
-      // Dispatch a custom event with the image IDs
-      const event = new CustomEvent('imageGenerationComplete', {
-        detail: { imageGeneration, imageIds }
+  // Process images synchronously to get imageIds before returning
+  // This ensures the canvas object can be saved with imageIds immediately
+  try {
+    const { imageGeneration: updatedImageGeneration, imageIds } =
+      await triggerBackgroundProcessing(imageGeneration.id, {
+        images: result.images,
+        status: RequestStatus.COMPLETED
       });
-      window.dispatchEvent(event);
-    })
-    .catch((error) => {
-      logger.error(
-        'Background processing failed',
-        error instanceof Error ? error : { cause: String(error) },
-        {
-          imageGenerationId: imageGeneration.id
-        }
-      );

-      // Notify user about the failure via custom event
-      const errorEvent = new CustomEvent('imageGenerationProcessingFailed', {
-        detail: {
-          imageGenerationId: imageGeneration.id,
-          error: error instanceof Error ? error.message : String(error)
-        }
-      });
-      window.dispatchEvent(errorEvent);
+    // Dispatch event for any listeners (e.g., cache updates)
+    const event = new CustomEvent('imageGenerationComplete', {
+      detail: { imageGeneration: updatedImageGeneration, imageIds }
     });
+    window.dispatchEvent(event);

-  return {
-    id: imageGeneration.id,
-    images: result.images,
-    requestStatus: RequestStatus.COMPLETED
-  };
+    return {
+      id: imageGeneration.id,
+      images: result.images,
+      imageIds,
+      requestStatus: RequestStatus.COMPLETED
+    };
+  } catch (error) {
+    logger.error(
+      'Background processing failed',
+      error instanceof Error ? error : { cause: String(error) },
+      {
+        imageGenerationId: imageGeneration.id
+      }
+    );
+
+    // Notify user about the failure via custom event
+    const errorEvent = new CustomEvent('imageGenerationProcessingFailed', {
+      detail: {
+        imageGenerationId: imageGeneration.id,
+        error: error instanceof Error ? error.message : String(error)
+      }
+    });
+    window.dispatchEvent(errorEvent);
+
+    // Still return the result with images, just without imageIds
+    // The image will still display, but won't persist properly
+    return {
+      id: imageGeneration.id,
+      images: result.images,
+      requestStatus: RequestStatus.COMPLETED
+    };
+  }
 }

